"""Conservative .dockerignore generator for Python projects."""

from dockseed.models import GenerationResult, ProjectModel


def generate_dockerignore(model: ProjectModel) -> GenerationResult:
    """Generate a deterministic, safe .dockerignore file for the given ProjectModel."""
    lines: list[str] = [
        "# Generated by Dockseed",
        "",
        "# Version control",
        ".git",
        ".gitignore",
        ".gitattributes",
        "",
        "# Virtual environments",
        ".venv/",
        "venv/",
        "env/",
        "",
        "# Python bytecode and caches",
        "__pycache__/",
        "*.py[cod]",
        "*$py.class",
        "",
        "# Testing, linting, and type-checking caches",
        ".pytest_cache/",
        ".coverage",
        "htmlcov/",
        ".mypy_cache/",
        ".ruff_cache/",
        ".tox/",
        ".nox/",
        "tests/",
        "",
        "# Build and distribution artifacts",
        "build/",
        "dist/",
        "*.egg-info/",
        "",
        "# Local environment secrets (preserve templates)",
        ".env",
        ".env.*",
        "!.env.example",
        "!.env.template",
        "!.env.sample",
        "",
        "# Container and IDE files",
        "Dockerfile",
        ".dockerignore",
        "docker-compose*.yml",
        ".vscode/",
        ".idea/",
    ]

    content = "\n".join(lines) + "\n"
    return GenerationResult(content=content)
